fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // As the problem stipulates, we assume arr1.len() == arr2.len().
    // For empty arrays, this will correctly return true.
    arr1.iter()
        .zip(arr2.iter())
        .all(|(a, b)| a > b)
}

